import{j as t}from"./blog-pages-CPaMOKsP.js";import{I as e}from"./I18nErpPage-DpeGnoBT.js";import"./PillarHubNav-Bef1r64A.js";import"./badge-DyJEh5NS.js";const i={heroBadge:"نظام إدارة فحوصات الاختبارات غير المتلفة",heroTitle:"برنامج تخطيط موارد المؤسسات للاختبارات غير المتلفة في دبي",heroSubtitle:"نظام إدارة الفحص لشركات التفتيش الإماراتية",heroIntro:"نظام تخطيط موارد مصمم خصيصًا لشركات الاختبارات غير المتلفة في دبي والإمارات العربية المتحدة. أتمتة متابعة شهادات CSWIP و ASNT و PCN، وجدولة فحوصات أدنوك، وإصدار تقارير PDF خلال دقائق بدلًا من ساعات.",ctaPrimary:"اطلب عرضًا توضيحيًا في دبي",ctaSecondary:"English version",statCompanies:"شركة فحص تستخدم النظام",statRating:"متوسط تقييم العملاء",statAdminReduction:"تقليل الوقت الإداري",statModules:"وحدات رئيسية للاختبارات غير المتلفة",marketContextLabel:"سياق سوق الاختبارات غير المتلفة",painPointsTitle:"لماذا تختار فرق الاختبارات غير المتلفة في دبي نظام أتلانتيس؟",painPointsSubtitle:"ثلاث نقاط ألم تشغيلية حرجة يتم القضاء عليها منذ اليوم الأول للنشر",problemLabel:"المشكلة",solutionLabel:"الحل",modulesTitle:"ست وحدات أساسية لشركات الاختبارات غير المتلفة",modulesSubtitle:"كل وحدة مصممة خصيصًا لقطاع التفتيش الصناعي وليست برنامج أعمال عامًا",roiTitle:"العائد على الاستثمار في دبي",faqTitle:"الأسئلة الشائعة — نظام أتلانتيس في دبي",alsoServingTitle:"خدمات أخرى",finalCtaTitle:"هل أنت مستعد لتحديث عمليات الاختبارات غير المتلفة في دبي؟",finalCtaBody:"انضم إلى شركات التفتيش في دبي وجبل علي وحقول الخفجي البحرية التي استبدلت جداول البيانات بنظام أتلانتيس. اطلب عرضًا توضيحيًا مخصصًا.",finalCtaPrimary:"اطلب عرضًا توضيحيًا",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function s(){return t.jsx(e,{lang:"ar",dir:"rtl",city:"دبي",countryCode:"AE",countryName:"الإمارات العربية المتحدة",slug:"ndt-erp-dubai",canonicalPath:"/ar/ndt-erp-dubai",englishPath:"/ndt-erp-dubai",pageTitle:"برنامج تخطيط موارد الاختبارات غير المتلفة في دبي | نظام إدارة الفحص | أتلانتيس NDT",pageDescription:"نظام تخطيط موارد للاختبارات غير المتلفة لشركات الفحص في دبي والإمارات. أتمتة متابعة شهادات CSWIP و ASNT، وإصدار تقارير متوافقة مع متطلبات أدنوك، وجدولة فحوصات API 510 و API 570.",keywords:"برنامج NDT دبي, نظام إدارة فحص الإمارات, ASNT, CSWIP, أدنوك, جبل علي, الرويس, ISO 9712",marketContext:"تُعدّ دبي المركز التجاري واللوجستي لقطاع النفط والغاز في دول مجلس التعاون الخليجي، وتستضيف المقار الإقليمية لكبرى الشركات المشغّلة ومقاولي الهندسة والمشتريات والإنشاء (EPC) ومزودي خدمات التفتيش. تعمل شركات الاختبارات غير المتلفة في الإمارات عبر مشاريع متنوعة تشمل صيانة المنصات البحرية وتوسعة منشآت الرويس، مما يستلزم متابعة دقيقة لشهادات المفتشين وفق متطلبات أدنوك ومتطلبات العملاء. يدمج نظام أتلانتيس لتخطيط موارد الاختبارات غير المتلفة جدولة الفحص وسجلات أفراد CSWIP و ASNT و PCN وإصدار تقارير PDF في منصة سحابية واحدة مصممة لإيقاع العمليات السريع في الخليج العربي. كما يدعم النظام التكامل مع معايير الشركة الإماراتية ACS-01 ومتطلبات ZADCO و ADMA-OPCO القديمة لشركات الفحص التي ما تزال تخدم الأصول البحرية في حقول أبوظبي، وإمكانية إعداد تقارير بصيغة بوابة موردي أدنوك ICAPS.",roiBody:"تشير بيانات عملاء أتلانتيس في دبي إلى تقليل الوقت الإداري بنسبة 40% خلال الأشهر الستة الأولى من النشر، وانخفاض زمن إعداد تقرير API 510 من ثلاث ساعات إلى خمس دقائق. اختفت تنبيهات انتهاء شهادات CSWIP و ASNT المفاجئة بفضل التذكيرات الآلية قبل 90 يومًا، وأصبح إعداد ملف التدقيق لمراجعات أدنوك متاحًا بنقرة واحدة. لفريق فحص مكوّن من اثني عشر فنيًا في جبل علي، يمثل ذلك توفيرًا سنويًا يتراوح بين 60,000 و85,000 درهم إماراتي، قبل احتساب قيمة تجنب فقدان اعتماد العقود.",painPoints:[{title:"متطلبات أدنوك المعقدة",problem:"يجب على شركات الفحص العاملة في منشآت أدنوك بدبي وأبوظبي الالتزام بصيغ تقارير محددة ومتطلبات اعتماد المفتشين وفق ACS-01، وهي متطلبات تتغير دوريًا وتصعب متابعتها يدويًا.",solution:"يحتوي نظام أتلانتيس على قوالب تقارير معتمدة مسبقًا متوافقة مع متطلبات أدنوك ACS-01، مع تحديثات تلقائية عند صدور إصدارات جديدة من المعايير، ممّا يضمن استمرارية الاعتماد كمورد."},{title:"إعداد التقارير اليدوي",problem:"يُهدر فنيو الاختبارات غير المتلفة في دبي ساعات في تنسيق تقارير CSWIP وتقارير API 510 يدويًا في برامج معالجة النصوص، مع أخطاء نسخ ولصق متكررة.",solution:"أصدر تقريرًا كاملًا بصيغة API بشعار شركتك وختمك الرقمي في أقل من خمس دقائق مباشرةً من البيانات الميدانية، دون إعادة تنسيق."},{title:"متابعة شهادات الفرق الكبيرة",problem:"تدير شركات الفحص في دبي مجموعات فنيين كبيرة بشهادات CSWIP و ASNT و PCN ومؤهلات بحرية متعددة، ويصعب على المشرفين متابعة تواريخ انتهاء كل شهادة قبل التعبئة لمشاريع أدنوك.",solution:"تتبع تلقائي لكل شهادة مع تنبيهات بريد إلكتروني قبل 90 و60 و30 يومًا من انتهاء الصلاحية، تُرسل إلى الفني ومشرفه المباشر."}],modules:[{title:"جدولة الفحص وإدارة أوامر العمل",description:"أتمتة احتساب فترات الفحص وفقًا لمعايير API 510 و API 570 و API 653 وفترات الفحص القائم على المخاطر المعتمدة من أدنوك. تخصيص الفنيين والمعدات لأوامر العمل في ثوانٍ.",features:["احتساب تلقائي لفترات API 510/570/653","جدولة الفحص القائم على المخاطر (RBI)","مصفوفة توفر الفنيين","تدفقات اعتماد أوامر العمل","وصول ميداني للمفتشين عبر الهاتف"]},{title:"تتبع شهادات الأفراد",description:"مركز سجلات شهادات ASNT SNT-TC-1A و ISO 9712 و PCN و CSWIP والمؤهلات الإماراتية الخاصة بكل عميل. تنبيهات تلقائية قبل 90 و60 و30 يومًا من الانتهاء.",features:["تنبيهات انتهاء ASNT و CSWIP","متابعة ISO 9712 و PCN","مصفوفة المؤهلات وفق ممارسة العميل المكتوبة","رسائل تذكير تلقائية بالتجديد","تصدير شهادات PDF جاهزة للتدقيق"]},{title:"إصدار تقارير الفحص",description:"أنشئ تقارير فحص احترافية بصيغة PDF وفقًا لمعايير API و ASME وقوالب أدنوك مباشرة من بيانات الإدخال الميدانية.",features:["قوالب تقارير الأوعية الضاغطة API 510","صيغ فحص الأنابيب API 570","تقارير فحص الخزانات API 653","منشئ قوالب مخصصة لأدنوك","تكامل التوقيع الرقمي والختم"]},{title:"إدارة بيانات التآكل",description:"سجّل قراءات السماكة ومعدلات التآكل وحسابات العمر المتبقي لأصول الرويس وجبل علي. اعرض اتجاهات التدهور بمخططات ملونة.",features:["قاعدة بيانات قياسات السماكة بالموجات فوق الصوتية","مخططات اتجاه معدل التآكل","احتساب العمر المتبقي وتاريخ التقاعد","تنبيهات نسبة فقدان السماكة","تصدير تقييم API 579"]},{title:"سجل الأصول وإدارة المعدات",description:"احتفظ بسجل رقمي كامل للأصول مع تتبع حالة معايرة المعدات وأدوات الفحص.",features:["هيكلية أصول مرتبطة بمخططات P&ID","متتبع تواريخ استحقاق معايرة المعدات","وسم الأصول برموز QR والباركود","سجل فحص تاريخي لكل أصل","تصنيف المخاطر ودرجة الأهمية"]},{title:"لوحة الامتثال",description:"رؤية فورية لامتثال متطلبات أدنوك و API و ISO 55000 في الإمارات. لوحة قيادة تنفيذية مع تنبيهات الفحوصات المتأخرة.",features:["لوحة تنبيه الفحوصات المتأخرة","نظرة عامة على حالة الامتثال متعدد العملاء","تقارير مؤشرات الأداء الرئيسية","تنبيهات تغييرات اللوائح","تقارير ملخص تنفيذي"]}],integrations:["تكامل مع أنظمة أدنوك ACS-01","تكامل SAP S/4HANA PM","ربط مؤهلات CSWIP","محاذاة ISO 55000 لإدارة الأصول","سجلات أصول DNV GL","بوابة موردي أدنوك ICAPS","صيغ تقارير ZADCO و ADMA","تكامل مع شركة المنطقة الحرة بجبل علي (JAFZA)"],faqs:[{question:"هل النظام معتمد للاستخدام مع شركات أدنوك التشغيلية؟",answer:"يستخدم النظام عدة شركات فحص معتمدة كموردين لدى أدنوك للأعمال البحرية والبرية. تحتوي مكتبة القوالب على إصدارات معتمدة من تقارير API 510 و API 570 معدّلة لاستيفاء متطلبات أدنوك ACS-01 لإعداد تقارير الفحص، وهي قابلة للتعديل وفق متطلبات كل عقد محدد."},{question:"ما هي اللغات المدعومة لإصدار التقارير؟",answer:"يدعم النظام إصدار تقارير ثنائية اللغة (العربية والإنجليزية) في نفس الملف PDF، مما يلبي متطلبات العملاء في الإمارات الذين يفضلون التقارير ثنائية اللغة لأغراض التدقيق الداخلي. يمكن أيضًا إصدار تقارير منفصلة بالعربية فقط أو الإنجليزية فقط حسب طلب العميل."},{question:"هل يدعم النظام عمليات الفحص البحرية في الخليج العربي؟",answer:"نعم. يحتوي النظام على وحدة مخصصة للعمليات البحرية تشمل متابعة شهادات الفنيين البحريين (OPITO BOSIET, FOET)، وفترات فحص PSSR 2000 للأنابيب البحرية، وقوالب تقارير متوافقة مع متطلبات شركات التشغيل البحرية في الخليج. يعمل التطبيق دون اتصال أثناء العمل على المنصات البحرية ويتزامن عند استعادة الاتصال."},{question:"كيف يتعامل النظام مع متطلبات بلدية دبي للسجلات الصناعية؟",answer:"يتضمن النظام نموذجًا للامتثال متوافقًا مع متطلبات بلدية دبي وهيئة تنظيم الكهرباء والماء (DEWA) لسجلات الفحص الصناعي. يحتفظ النظام بسجلات يمكن تدقيقها لكل قراءة فحص مع المعرّف الزمني وهوية الفني ومرجع الإجراء المعتمد."}],ui:i})}export{s as default};
